reject(fn()=>CashierSchedule::block(1,1,$cpEnd,$cpStart,'absence','Invalid dates'),'invalid block range rejected');
reject(fn()=>CashierSchedule::block(1,1,$cpStart,$cpEnd,'absence',''),'block requires reason');
